# Generated by enocone's release workflow (.github/scripts/homebrew-formula.sh).
class Enocone < Formula
  desc "Business flows as Markdown: reviewed by people, run as end-to-end tests, written with AI"
  homepage "https://enoc.one"
  version "0.2.11"
  license any_of: ["MIT", "Apache-2.0"]

  # Each archive holds the binary and the Playwright driver it runs browsers
  # with (playwright-driver/, beside the binary). macOS on Intel isn't built.
  on_macos do
    on_arm do
      url "https://github.com/driftwerk/enocone/releases/download/v0.2.11/enocone-aarch64-apple-darwin.tar.gz"
      sha256 "db2256ac4bcd129f0e94d97d081557709d783508e03a7a1ad572906179746a7c"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/driftwerk/enocone/releases/download/v0.2.11/enocone-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "2216cb13906950b599a52ed831da0e59ea173898db5d83659f23f2e401c45a13"
    end
    on_arm do
      url "https://github.com/driftwerk/enocone/releases/download/v0.2.11/enocone-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "3fec0302d346b53e5c5a592dcdadc408e8d0d37e55a9a64633c773636e16f035"
    end
  end

  def install
    # The binary finds the driver beside its real path, so both live in libexec.
    libexec.install "enocone", "playwright-driver"
    bin.install_symlink libexec/"enocone"
  end

  def caveats
    <<~EOS
      Download Chromium for browser steps (once per Playwright version):

        enocone install-browsers

      Then, in your project:

        enocone init --name <project> --hub https://enoc.one

      That writes enocone.toml, a CI workflow and .mcp.json, so Claude Code or
      Cursor in that folder can use enocone's MCP server. To use it in every
      project with Claude Code instead:

        claude mcp add enocone --scope user -- #{opt_bin}/enocone mcp

      enocone doctor checks the installation.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/enocone --version")
    assert_match "bundled with enocone", shell_output("#{bin}/enocone doctor")
  end
end
